/* Reader: a bounded flex surface with its own content scroller; the toolbar
   (and its Back affordance) stays persistent while the message stack scrolls. */
.reader-pane,
.reader {
  min-height: 0;
  min-width: 0;
}

.reader-pane {
  display: flex;
  flex-direction: column;
  padding: 0.5rem 0.75rem;
}

.reader {
  flex: 1;
  display: flex;
  flex-direction: column;
}

.reader:focus {
  outline: none;
}

.reader-toolbar {
  flex: 0 0 auto;
  display: flex;
  gap: 0.5rem;
  align-items: baseline;
  flex-wrap: wrap;
  padding-bottom: 0.4rem;
  border-bottom: 1px solid var(--rule);
  margin-bottom: 0.5rem;
}

.reply-source-label {
  color: var(--text-secondary);
  font-size: var(--type-body);
}

.reader-scroll {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
}

/* Headline at the strong weight: the subject leads the reader without a third size. */
.reader-subject {
  font-size: var(--type-headline);
  font-weight: var(--weight-strong);
  line-height: var(--leading-headline);
  overflow-wrap: anywhere;
}

.reader-pending {
  font-style: italic;
}

.messages {
  list-style: none;
  padding: 0;
  margin: 0;
}

.message {
  border-top: 1px solid var(--rule);
  padding: 0.4rem 0.4rem 0.6rem;
  margin-bottom: 0.5rem;
}

/*
 * Current-message treatment: an accent-purple bar (color) plus a non-color
 * indication (soft warm fill and a primary-color sender) so the focused
 * message never relies on color alone.
 */
.message.message-active {
  background: var(--focus-fill);
  box-shadow: inset 3px 0 0 var(--focus-accent);
}

.message.message-active .message-from {
  color: var(--text-primary);
  font-weight: var(--weight-strong);
}

/* Collapsed headers stay compact: the recipient line appears only when expanded. */
.message-toggle {
  display: flex;
  align-items: baseline;
  gap: 0.75rem;
  width: 100%;
  text-align: left;
  font-size: var(--type-body);
  color: var(--text-secondary);
  background: transparent;
  border: 0;
  padding: 0.1rem 0.2rem;
  flex-wrap: wrap;
}

.message-toggle[aria-expanded='false'] .message-to {
  display: none;
}

.message-time {
  font-variant-numeric: tabular-nums;
}

.message-body {
  white-space: pre-wrap;
  font-family: var(--font-mono);
  font-size: var(--type-mono);
  line-height: var(--leading-mono);
  color: var(--text-primary);
  overflow-wrap: anywhere;
  margin: 0.4rem 0;
}

/* Per-message participant details disclosure (native details/summary). */
.message-details {
  font-size: var(--type-body);
  margin-top: 0.4rem;
}

.message-details summary {
  cursor: pointer;
  color: var(--text-secondary);
  width: max-content;
}

.message-fields {
  display: grid;
  gap: 0.2rem;
  padding: 0.3rem 0;
}

.message-field {
  display: flex;
  gap: 0.4rem;
  min-width: 0;
}

.message-field-label {
  flex: 0 0 auto;
  color: var(--text-secondary);
}

.message-field-recipients {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

/* Participant context controls: hover/focus context, never navigation. */
.participant {
  overflow-wrap: anywhere;
  text-decoration: underline dotted;
  cursor: default;
}

